def is_boss(npc_id: int, dungeon_id: int = None) -> bool:
    if not npc_id:
        return False
    if dungeon_id and dungeon_id in DUNGEON_BOSSES:
        if npc_id in DUNGEON_BOSSES[dungeon_id]:
            return True
    return npc_id in BOSS_IDS

def get_boss_name(npc_id: int) -> str:
    return BOSS_NAMES.get(npc_id, "")
